import httpx
from api_fetch import iter_items


def open_ticket_titles(client: httpx.Client, project: str) -> list[str]:
    """Return the titles of all open tickets for the given project, paginating as needed."""
    params = {"status": "open", "project": project}
    return [item["title"] for item in iter_items(client, "/tickets", params=params)]

